from collections import deque
def enclosed_fill(g, bgv, fillv):
    R,C=len(g),len(g[0])
    seen=[[False]*C for _ in range(R)]
    q=deque()
    for r in range(R):
        for c in (0,C-1):
            if g[r][c]==bgv and not seen[r][c]: seen[r][c]=True; q.append((r,c))
    for c in range(C):
        for r in (0,R-1):
            if g[r][c]==bgv and not seen[r][c]: seen[r][c]=True; q.append((r,c))
    while q:
        r,c=q.popleft()
        for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<R and 0<=nc<C and g[nr][nc]==bgv and not seen[nr][nc]:
                seen[nr][nc]=True; q.append((nr,nc))
    out=[row[:] for row in g]
    for r in range(R):
        for c in range(C):
            if g[r][c]==bgv and not seen[r][c]: out[r][c]=fillv
    return out
